package com.revivex.service; import com.revivex.domain.RecoveryCase; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; @Service public class ExplanationService { private final boolean enabled; public ExplanationService(@Value("${revivex.llm.enabled:false}")boolean enabled){this.enabled=enabled;} public String explain(RecoveryCase c){String prefix=enabled?"AI-assisted explanation (bounded; financial decision remains deterministic): ":"Deterministic explanation: "; return prefix+c.getReasoning()+" Recovery probability="+Math.round(c.getRecoveryProbability()*100)+"%. Expected net recovery="+c.getExpectedNetRecovery()+". Policy="+c.getPolicyReason()+".";} }
